// This module is the shared executable assertion for every runtime that uses
// the subpath-pattern fixture. Keep the expected values here so Node.js, the
// compartment mapper, and Endor exercise the same fixture behavior.
import * as namespace from './main.js';

const expected = {
  alpha: 'alpha',
  betaGamma: 'beta-gamma',
  exact: 'exact-match',
  helper: 'helper',
  specificity: 'specific',
};

for (const [name, value] of Object.entries(expected)) {
  if (namespace[name] !== value) {
    throw new Error(
      `subpath pattern fixture: expected ${name} to be ${JSON.stringify(value)}, got ${JSON.stringify(namespace[name])}`,
    );
  }
}

export * from './main.js';
